"use client";

import SearchIcon from "@mui/icons-material/Search";
import PictureAsPdfOutlinedIcon from "@mui/icons-material/PictureAsPdfOutlined";
import TableViewOutlinedIcon from "@mui/icons-material/TableViewOutlined";
import {
  Button,
  InputAdornment,
  Paper,
  SxProps,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TablePagination,
  TableRow,
  TableSortLabel,
  TextField,
  Theme
} from "@mui/material";
import { ReactNode, isValidElement, useEffect, useMemo, useState } from "react";
import dicConstant from "@/constants/Constant.json";

type CellAlign = "left" | "right" | "center";

export type DataGridColumn<T extends Record<string, ReactNode>> = {
  field: keyof T;
  headerName: string;
  align?: CellAlign;
  width?: number;
  sortable?: boolean;
  filterable?: boolean;
  exportable?: boolean;
};

type CommonDataGridProps<T extends Record<string, ReactNode>> = {
  columns: DataGridColumn<T>[];
  rows: T[];
  rowIdField?: keyof T;
  defaultPageSize?: number;
  pageSizeOptions?: number[];
  exportFileName?: string;
  showExportOptions?: boolean;
  emptyMessage?: string;
  withPaper?: boolean;
  sx?: SxProps<Theme>;
};

// Renders a generic client-side data grid with filter, sort, pagination, and optional export.
export default function CommonDataGrid<T extends Record<string, ReactNode>>({
  columns,
  rows,
  rowIdField,
  defaultPageSize = 5,
  pageSizeOptions = [5, 10, 25],
  exportFileName = dicConstant.commonDataGrid.defaultExportFileName,
  showExportOptions = false,
  emptyMessage = dicConstant.commonDataGrid.emptyMessage,
  withPaper = true,
  sx
}: CommonDataGridProps<T>) {
  // Functional responsibility:
  // - Render a reusable table with client-side filter, sort, pagination, and optional exports.
  // Inputs:
  // - columns/rows define table shape + data.
  // - rowIdField controls stable row keys.
  // - showExportOptions/exportFileName control export UI and file naming.
  // Output:
  // - Renders tabular UI (optionally wrapped in Paper) and export actions.
  // Failure behavior:
  // - If data is empty after filtering, renders emptyMessage row (no exception thrown).
  // - If PDF popup is blocked, export handler safely returns without crashing.
  const [searchTerm, setSearchTerm] = useState("");
  const [sortBy, setSortBy] = useState<keyof T | null>(null);
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("asc");
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(defaultPageSize);

  const filteredAndSortedRows = useMemo(() => {
    // Logical flow:
    // 1) Apply text filtering on filterable columns.
    // 2) Apply sorting on the selected sortable column.
    const searchableColumns = columns.filter((column) => column.filterable !== false);

    const filtered = rows.filter((row) => {
      if (!searchTerm.trim()) {
        return true;
      }
      const query = searchTerm.toLowerCase();
      return searchableColumns.some((column) => {
        const value = row[column.field];
        if (typeof value === "string" || typeof value === "number") {
          return String(value).toLowerCase().includes(query);
        }
        return false;
      });
    });

    if (!sortBy) {
      return filtered;
    }

    const sorted = [...filtered].sort((a, b) => {
      const aValue = a[sortBy];
      const bValue = b[sortBy];

      if ((typeof aValue !== "string" && typeof aValue !== "number") || (typeof bValue !== "string" && typeof bValue !== "number")) {
        return 0;
      }

      if (aValue < bValue) {
        return sortDirection === "asc" ? -1 : 1;
      }
      if (aValue > bValue) {
        return sortDirection === "asc" ? 1 : -1;
      }
      return 0;
    });

    return sorted;
  }, [columns, rows, searchTerm, sortBy, sortDirection]);

  const handleSort = (field: keyof T, sortable: boolean | undefined) => {
    if (sortable === false) {
      return;
    }
    if (sortBy === field) {
      setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"));
      return;
    }
    setSortBy(field);
    setSortDirection("asc");
  };

  useEffect(() => {
    setPage(0);
  }, [searchTerm, sortBy, sortDirection, rowsPerPage]);

  const paginatedRows = useMemo(() => {
    // Logical flow:
    // Slice filtered/sorted rows for current page window.
    const start = page * rowsPerPage;
    return filteredAndSortedRows.slice(start, start + rowsPerPage);
  }, [filteredAndSortedRows, page, rowsPerPage]);

  const exportColumns = columns.filter((column) => column.exportable !== false);

  const toText = (value: ReactNode): string => {
    if (value === null || value === undefined) {
      return "";
    }
    if (typeof value === "string" || typeof value === "number") {
      return String(value);
    }
    if (Array.isArray(value)) {
      return value.map((item) => toText(item)).join(" ");
    }
    if (isValidElement(value)) {
      const props = value.props as { children?: ReactNode };
      return toText(props.children);
    }
    return "";
  };

  const toCsvCell = (value: string) => `"${value.replace(/"/g, "\"\"")}"`;

  const handleExportExcel = () => {
    // Output:
    // - Downloads a UTF-8 CSV file (Excel-friendly) containing exported columns + filtered/sorted rows.
    // Failure behavior:
    // - If browser blocks download, no throw from this module.
    const headers = exportColumns.map((column) => toCsvCell(column.headerName)).join(",");
    const body = filteredAndSortedRows
      .map((row) =>
        exportColumns
          .map((column) => toCsvCell(toText(row[column.field])))
          .join(",")
      )
      .join("\n");
    const csvContent = `${headers}\n${body}`;
    const blob = new Blob([`\uFEFF${csvContent}`], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${exportFileName}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleExportPdf = () => {
    // Output:
    // - Opens print-friendly page for PDF save/print.
    // Failure behavior:
    // - If popup blocked (window.open returns null), exits gracefully.
    const headerHtml = exportColumns.map((column) => `<th>${column.headerName}</th>`).join("");
    const rowHtml = filteredAndSortedRows
      .map(
        (row) =>
          `<tr>${exportColumns
            .map((column) => `<td>${toText(row[column.field])}</td>`)
            .join("")}</tr>`
      )
      .join("");

    const printWindow = window.open("", "_blank", "width=1000,height=700");
    if (!printWindow) {
      return;
    }

    printWindow.document.write(`
      <html>
        <head>
          <title>${exportFileName}</title>
          <style>
            body { font-family: Arial, sans-serif; padding: 24px; }
            h2 { margin: 0 0 16px 0; }
            table { width: 100%; border-collapse: collapse; }
            th, td { border: 1px solid #d0d7de; padding: 8px; text-align: left; font-size: 12px; }
            th { background: #f2f4f7; }
          </style>
        </head>
        <body>
          <h2>${exportFileName}</h2>
          <table>
            <thead><tr>${headerHtml}</tr></thead>
            <tbody>${rowHtml}</tbody>
          </table>
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.focus();
    printWindow.print();
  };

  const table = (
    <>
      <Stack
        direction={{ xs: "column", sm: "row" }}
        spacing={1.2}
        alignItems={{ sm: "center" }}
        justifyContent="space-between"
        sx={{ mt: 1, mb: 1.5 }}
      >
        <TextField
          placeholder={dicConstant.commonDataGrid.filterPlaceholder}
          value={searchTerm}
          onChange={(event) => setSearchTerm(event.target.value)}
          sx={{ minWidth: { xs: "100%", sm: 320 } }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon fontSize="small" />
              </InputAdornment>
            )
          }}
        />
        {showExportOptions ? (
          <Stack direction="row" spacing={1}>
            <Button
              variant="outlined"
              size="small"
              startIcon={<TableViewOutlinedIcon />}
              onClick={handleExportExcel}
            >
              {dicConstant.commonDataGrid.exportExcel}
            </Button>
            <Button
              variant="outlined"
              size="small"
              startIcon={<PictureAsPdfOutlinedIcon />}
              onClick={handleExportPdf}
            >
              {dicConstant.commonDataGrid.exportPdf}
            </Button>
          </Stack>
        ) : null}
      </Stack>
      <Table>
        <TableHead>
          <TableRow>
            {columns.map((column) => (
              <TableCell
                key={String(column.field)}
                align={column.align ?? "left"}
                sx={column.width ? { width: column.width } : undefined}
              >
                <TableSortLabel
                  active={sortBy === column.field}
                  direction={sortBy === column.field ? sortDirection : "asc"}
                  onClick={() => handleSort(column.field, column.sortable)}
                  hideSortIcon={column.sortable === false}
                >
                  {column.headerName}
                </TableSortLabel>
              </TableCell>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {filteredAndSortedRows.length === 0 ? (
            <TableRow>
              <TableCell colSpan={columns.length} align="center">
                {emptyMessage}
              </TableCell>
            </TableRow>
          ) : (
            paginatedRows.map((row, index) => (
              <TableRow
                key={rowIdField ? String(row[rowIdField]) : `${page}-${index}`}
                hover
              >
                {columns.map((column) => (
                  <TableCell key={`${String(column.field)}-${index}`} align={column.align ?? "left"}>
                    {row[column.field]}
                  </TableCell>
                ))}
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
      <TablePagination
        component="div"
        count={filteredAndSortedRows.length}
        page={page}
        onPageChange={(_, nextPage) => setPage(nextPage)}
        rowsPerPage={rowsPerPage}
        onRowsPerPageChange={(event) => {
          setRowsPerPage(parseInt(event.target.value, 10));
        }}
        rowsPerPageOptions={pageSizeOptions}
      />
    </>
  );

  if (!withPaper) {
    return table;
  }

  return <Paper sx={sx}>{table}</Paper>;
}
